            _ = assert((max_waiters != 0));
            const raw_ptr = (&ptr.raw);
            _ = &raw_ptr;
            const woken_count = asm volatile ("local.get %[ptr]\nlocal.get %[waiters]\nmemory.atomic.notify 0\nlocal.set %[ret]"
            : [ret] "=r" (-> u32),
            : [ptr] "r" (raw_ptr),
              [waiters] "r" (max_waiters),);
            _ = &woken_count;
    }
};

pub const Deadline = struct {
    timeout: ?u64,
    started: std.time.Timer,

pub fn init(expires_in_ns: ?u64) Deadline {
            var deadline: Deadline = undefined;
            _ = &deadline;
            deadline.timeout = expires_in_ns;
            if ((deadline.timeout != null)) {
                deadline.started = ((std.time.Timer.start()) catch unreachable);
            }
            return deadline;
    }

pub fn wait(self: *Deadline, ptr: *const atomic.Value(u32), expect: u32) TimeoutError!void {
            @branchHint(.cold);
            if ((self.timeout == null)) {
                _ = Futex.waitForever(ptr, expect);
                return;
            }
            const timeout_ns = self.timeout.?;
            const elapsed_ns = self.started.read();
            const until_timeout_ns = (blk_catch_1: { break :blk_catch_1 ((std.math.sub(u64, timeout_ns, elapsed_ns)) catch |__ce_1| { _ = &__ce_1; break :blk_catch_1 0; }); });
            return Futex.wait(ptr, expect, until_timeout_ns);
    }
};

const atomic = std.atomic;
const c = std.c;
const linux = std.os.linux;
const windows = std.os.windows;
pub const Futex = @This();
pub const Impl = (switch (builtin.os.tag) {
.windows => WindowsImpl,
.linux => LinuxImpl,
.freebsd => FreebsdImpl,
else => (if (builtin.os.tag.isDarwin()) DarwinImpl else (if (builtin.target.isWasm()) WasmImpl else UnsupportedImpl)),
});

pub fn wait(ptr: *const atomic.Value(u32), expect: u32, timeout_ns: ?u64) !void {
        @branchHint(.cold);
        if (timeout_ns) |t| {
            _ = &t;
            if ((t == 0)) {
                if ((ptr.load(.seq_cst) != expect)) {
                    return;
                }
                return error.Timeout;
            }
        }
        return Impl.wait(ptr, expect, timeout_ns);
}

pub fn waitForever(ptr: *const atomic.Value(u32), expect: u32) void {
        @branchHint(.cold);
        while (true) {
            _ = (blk_catch_2: { break :blk_catch_2 ((Impl.wait(ptr, expect, null)) catch |e| { _ = &e; if ((e == error.Timeout)) {
                continue;
            }
            break; }); });
            break;
        }
}

pub fn wake(ptr: *const atomic.Value(u32), max_waiters: u32) void {
        if ((max_waiters == 0)) {
            return;
        }
        _ = Impl.wake(ptr, max_waiters);
}
